examples.template:
NavigationStack {
    MonarchNotificationCenter(
        items,
        now: {{now|date}},
        hasMore: {{hasMore}},
        onMarkRead: { id in read.insert(id) },
        onMarkAllRead: { read = Set(items.map(\.id)) },
        onLoadMore: {}
    ) {
        Button({{footer}}) {}
            .buttonStyle(.monarchLink(.inline))
    }
}
.environment(\.timeZone, .gmt)
.frame(minHeight: 480)

examples.setupTemplate:
@State private var read: Set<String> = []

private let source = [
    MonarchNotificationCenterItem(
        id: {{items.0.id}},
        title: {{items.0.title}},
        message: {{items.0.description}},
        time: {{items.0.time|date}},
        actorName: {{items.0.actor}}
    ),
    MonarchNotificationCenterItem(
        id: {{items.1.id}},
        title: {{items.1.title}},
        time: {{items.1.time|date}},
        actorName: {{items.1.actor}}
    ),
    MonarchNotificationCenterItem(
        id: {{items.2.id}},
        title: {{items.2.title}},
        message: {{items.2.description}},
        time: {{items.2.time|date}},
        isRead: {{items.2.read}},
        actorName: {{items.2.actor}}
    ),
    MonarchNotificationCenterItem(
        id: {{items.3.id}},
        title: {{items.3.title}},
        time: {{items.3.time|date}},
        isRead: {{items.3.read}}
    ),
]

private var items: [MonarchNotificationCenterItem] {
    source.map {
        MonarchNotificationCenterItem(
            id: $0.id,
            title: $0.title,
            message: $0.message,
            time: $0.time,
            isRead: $0.isRead || read.contains($0.id),
            actorName: $0.actorName
        )
    }
}

examples.code:
NavigationStack {
    MonarchNotificationCenter(
        items,
        now: Date(timeIntervalSince1970: 1_772_452_800),
        hasMore: true,
        onMarkRead: { id in read.insert(id) },
        onMarkAllRead: { read = Set(items.map(\.id)) },
        onLoadMore: {}
    ) {
        Button("Notification settings") {}
            .buttonStyle(.monarchLink(.inline))
    }
}
.environment(\.timeZone, .gmt)
.frame(minHeight: 480)
